package music.resonance.mobile;
import com.yausername.ffmpeg.FFmpeg;
import org.json.*;
import android.net.Uri;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

/** One low-priority analysis at a time. Only compact measurements survive. */
public final class SongAnalysis {
    private final ResonanceApp app;private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Set<String> queued=new HashSet<>();private volatile JSONObject job=Json.object("running",false);private volatile Process process;
    SongAnalysis(ResonanceApp app){this.app=app;}
    static String stamp(JSONObject t){return t.optString("path")+"|"+t.optLong("size")+"|"+t.optLong("modified")+"|"+t.optDouble("duration");}
    public JSONObject profile(String id){JSONObject t=app.library.track(id),p=app.library.setting("audioProfile:"+id);return p.optInt("version")==1&&stamp(t).equals(p.optString("stamp"))?p:new JSONObject();}
    public synchronized JSONObject status(String id){JSONObject p=profile(id);return Json.object("profile",p.length()==0?JSONObject.NULL:p,"edit",app.library.setting("playbackEdit:"+id),"job",Json.object("running",queued.contains(id),"id",job.optString("id"),"progress",job.optDouble("progress")),"error",stamp(app.library.track(id)).equals(app.library.setting("audioError:"+id).optString("stamp"))?app.library.setting("audioError:"+id).optString("message"):"");}
    public synchronized JSONObject request(String id,boolean force){if(app.library.track(id).length()==0)throw new IllegalArgumentException("Track unavailable");if(queued.contains(id)||!force&&(profile(id).length()>0||!status(id).optString("error").isEmpty()))return status(id);if(queued.size()>=8)return Json.object("profile",JSONObject.NULL,"edit",app.library.setting("playbackEdit:"+id),"job",Json.object("running",false),"error","Analysis queue is busy. Try again shortly.");app.library.setting("audioError:"+id,new JSONObject());queued.add(id);worker.execute(()->analyze(id));return status(id);}
    public JSONObject edit(String id,JSONObject data){JSONObject track=app.library.track(id);if(track.length()==0)throw new IllegalArgumentException("Track unavailable");app.library.setting("playbackEdit:"+id,SongProfile.range(data,track.optDouble("duration")));return status(id);}
    private void analyze(String id){File temporary=null,log=null;Process child=null;ScheduledExecutorService timer=Executors.newSingleThreadScheduledExecutor();android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);JSONObject track=app.library.track(id);String stamp=stamp(track);job=Json.object("running",true,"id",id,"progress",0);
        try{FFmpeg.INSTANCE.init(app);Uri uri=app.library.playbackUri(id,Uri.parse(track.optString("path")));String input;
            if("file".equals(uri.getScheme()))input=uri.getPath();else{temporary=File.createTempFile("song-analysis-",".audio",app.getCacheDir());long max=Math.min(512L*1024*1024,Math.max(0,app.getCacheDir().getUsableSpace()-64L*1024*1024));try(InputStream in=app.getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(temporary)){if(in==null)throw new IOException("File unavailable");byte[] b=new byte[65536];int n;long size=0;while((n=in.read(b))!=-1){if((size+=n)>max)throw new IOException("Not enough temporary space to analyze this linked file");out.write(b,0,n);}}input=temporary.getAbsolutePath();}
            log=File.createTempFile("song-analysis-",".log",app.getCacheDir());ProcessBuilder builder=new ProcessBuilder(new File(app.getApplicationInfo().nativeLibraryDir,"libffmpeg.so").getAbsolutePath(),"-hide_banner","-nostdin","-nostats","-threads","1","-filter_threads","1","-i",input,"-vn","-map","0:a:0","-af",SongProfile.FILTER,"-f","null","-");builder.environment().put("LD_LIBRARY_PATH",new File(app.getNoBackupFilesDir(),"youtubedl-android/packages/ffmpeg/usr/lib").getAbsolutePath());builder.environment().put("TMPDIR",app.getCacheDir().getAbsolutePath());builder.redirectError(log);child=builder.start();process=child;final Process running=child;timer.schedule(running::destroyForcibly,Math.max(120,Math.min(900,(long)(track.optDouble("duration")*.5))),TimeUnit.SECONDS);SongProfile reader=new SongProfile(track.optDouble("duration"));
            try(BufferedReader lines=new BufferedReader(new InputStreamReader(child.getInputStream()))){String line;long last=0;while((line=lines.readLine())!=null){reader.line(line);long now=System.currentTimeMillis();if(now-last>1000){last=now;job=Json.object("running",true,"id",id,"progress",reader.progress(track.optDouble("duration")));}}}
            if(child.waitFor()!=0)throw new IOException("This file could not be analyzed. Playback is still available.");JSONObject profile=reader.finish();if(profile.optDouble("duration")<.1)throw new IOException("No decodable audio found");if(stamp.equals(stamp(app.library.track(id)))){Json.put(profile,"stamp",stamp);Json.put(profile,"savedAt",System.currentTimeMillis());app.library.setting("audioProfile:"+id,profile);app.library.setting("audioError:"+id,new JSONObject());}
        }catch(Exception e){app.library.setting("audioError:"+id,Json.object("stamp",stamp,"message",e.getMessage()==null?"Analysis unavailable":e.getMessage()));}
        finally{if(child!=null&&child.isAlive())child.destroyForcibly();process=null;timer.shutdownNow();if(temporary!=null)temporary.delete();if(log!=null)log.delete();synchronized(this){queued.remove(id);job=Json.object("running",!queued.isEmpty(),"id","","progress",0);}}
    }
}
